/// The retirement sentence for `key`, "`<key>` is retired: <its
/// replacement>", or `None` when `key` is not one of
/// [`RETIRED_KEYS`].
pub fn retired_key(key: &str) -> Option<String> {
    RETIRED_KEYS
        .iter()
        .find(|(k, _)| *k == key)
        .map(|(k, replacement)| format!("`{k}` is retired: {replacement}"))
}

/// Refuse a config that lacks `key` but still holds one of the
/// retired keys under `table`, `[build]` or `[install]`, naming the
/// migration to the profile form: an old config would otherwise be
/// told only that `key` is missing. `Ok` when none is held, so the
/// caller reports the missing key as it always has. `label` prefixes
/// the error and `path` is the config file's.
pub fn refuse_retired(
    map: &std::collections::HashMap<String, String>,
    path: &Path,
    key: &str,
    table: &str,
    label: &str,
) -> Result<(), String> {
    let prefix = format!("{table}.");
    let held: Vec<String> = RETIRED_KEYS
        .iter()
        .filter(|(k, _)| k.starts_with(&prefix) && map.contains_key(*k))
        .map(|(k, _)| format!("`{k}`"))
        .collect();
    if held.is_empty() {
        return Ok(());
    }
    let (held, verb) = match held.len() {
        1 => (held.join(""), "is"),
        _ => (held.join(", "), "are"),
    };
    Err(format!(
        "{label}: {}: no `{key}`, and {held} {verb} retired: every build is a profile now, \\
         `[build] commands` filled from a `[profile.<name>]` table per build, its `cargo`, \\
         `bin`, and `suffix`, and the install is `[install] dir` and, optionally, \\
         `[install] commands` (`vc-x1 validate-config` names each retired key's replacement)",
        path.display()
    ))
}

